      hf.retiredSessions.push(hf.order.session);
      if (hf.retiredSessions.length > 8) hf.retiredSessions.shift();
      hfResetContext("session_changed"); hf.order = { session: m.session_id, epoch: null, sel: null };
    }
    if (hf.order.epoch !== null) {
