function hfUpdatePerfPanel() {
  var conn = (client && client.live) ? "在线" : "断开";
  var fpsEl = $("pcPresHz"), skipEl = $("pcSkip");
  var fps = fpsEl ? fpsEl.textContent : "--";
  var q = (hf.presented || hf.rawCount > 0) && skipEl ? skipEl.textContent : "--";
  hfSetText("gPerf", fps + " fps · queue_dropped " + q + " · " + conn,
